/* audio/effects/effect.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../../context.js";

export function install(P) {


  /* ---------- effects: render once into a static waveform ----------
   * The old player kept WaveShaper/Delay/Convolver nodes in the live graph for
   * the whole playback. That meant continuous real-time DSP, a permanently
   * running LFO and reverb impulse rebuilds on every slider move. It also made
   * the audible state and the checkboxes drift apart after a reload.
   * Now the same chain runs once in an OfflineAudioContext and the result is
   * a plain WAV blob used as the track source. Playback itself is just audio.
   */

  function anyFxEnabled() {
    return P.FX_KINDS.some((kind) => !!P.state[`${kind}Enabled`]);
  }

  function fxSnapshot() {
    const settings = { fx: {} };
    P.FX_KINDS.forEach((kind) => {
      settings.fx[`${kind}Enabled`] = !!P.state[`${kind}Enabled`];
    });
    Object.keys(P.FX_RANGES).forEach((key) => { settings.fx[key] = P.state[key]; });
    return settings;
  }

  function fxSettingsKey() {
    return JSON.stringify(P.fxSnapshot().fx);
  }

  function getDecodeContext() {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return null;
    if (P.decodeContext && P.decodeContext.state !== "closed") return P.decodeContext;
    try { P.decodeContext = new AudioContextClass(); } catch { P.decodeContext = null; }
    return P.decodeContext;
  }

  function decodeTrack(url) {
    if (!url || !window.fetch) return Promise.resolve(null);
    if (P.decodedTrackCache.has(url)) return P.decodedTrackCache.get(url);
    const task = (async () => {
      const context = P.getDecodeContext();
      if (!context) return null;
      const response = await fetch(url, { cache: "force-cache", credentials: "same-origin" });
      if (!response.ok) return null;
      const bytes = await response.arrayBuffer();
      return await context.decodeAudioData(bytes.slice(0));
    })().catch(() => null);
    // Decoded PCM is heavy: keep only a few files. A render already holding a
    // promise is unaffected when its map entry is evicted.
    if (P.decodedTrackCache.size >= P.MAX_DECODED_TRACKS) {
      P.decodedTrackCache.delete(P.decodedTrackCache.keys().next().value);
    }
    P.decodedTrackCache.set(url, task);
    return task;
  }

  /* Live preview: the same chain runs in the realtime context while knobs
   * move. Once the idle timer fires, renderTrackToWav() bakes an identical
   * static copy and playback switches to it, so there is no permanent LFO or
   * convolution load during steady playback. */
  function liveFxActive() {
    return !!P.state.current && P.anyFxEnabled() && !P.isTrackRendered(P.state.current);
  }

  function stopLiveFxOscillators() {
    P.liveFxOscillators.forEach((osc) => { try { osc.stop(); } catch {} });
    P.liveFxOscillators = [];
  }

  function stopLiveFx() {
    P.stopLiveFxOscillators();
    if (P.liveFxInputNode) { try { P.liveFxInputNode.disconnect(); } catch {} }
    if (P.liveFxOutputNode) { try { P.liveFxOutputNode.disconnect(); } catch {} }
    P.liveFxSignature = "";
  }

  function normalizeBakeDelay(value) {
    const n = Number(value);
    return Number.isFinite(n)
      ? Math.min(P.FX_BAKE_DELAY_MAX_MS, Math.max(P.FX_BAKE_DELAY_MIN_MS, Math.round(n)))
      : P.DEFAULT_FX_BAKE_DELAY_MS;
  }

  function bakeDelayMs() {
    return P.normalizeBakeDelay(P.state.fxBakeDelayMs);
  }

  function wireLiveFxOutput() {
    if (!P.liveFxOutputNode) return;
    try { P.liveFxOutputNode.disconnect(); } catch {}
    const target = P.state.eqEnabled && P.eqInputNode ? P.eqInputNode : P.outputDestination();
    try { P.liveFxOutputNode.connect(target); } catch {}
  }

  function ensureLiveFx() {
    const context = P.sharedAudioContext();
    if (!context || !P.anyFxEnabled()) { P.stopLiveFx(); return null; }
    if (!P.liveFxInputNode) P.liveFxInputNode = context.createGain();
    if (!P.liveFxOutputNode) P.liveFxOutputNode = context.createGain();
    const signature = P.fxSettingsKey();
    if (P.liveFxSignature !== signature) {
      P.stopLiveFxOscillators();
      // Replace the whole graph, not just its endpoints: a delay or convolver
      // tail from the previous settings would otherwise stay connected to a
      // reused output node and bleed into the new preview.
      if (P.liveFxInputNode) { try { P.liveFxInputNode.disconnect(); } catch {} }
      if (P.liveFxOutputNode) { try { P.liveFxOutputNode.disconnect(); } catch {} }
      P.liveFxInputNode = context.createGain();
      P.liveFxOutputNode = context.createGain();
      P.connectOfflineFxChain(context, P.liveFxInputNode, P.liveFxOutputNode, P.fxSnapshot(), P.liveFxOscillators);
      P.liveFxSignature = signature;
    }
    P.wireLiveFxOutput();
    return P.liveFxInputNode;
  }

  function syncLiveFx() {
    if (!P.audioContext) return;
    if (P.liveFxActive()) P.ensureLiveFx();
    else P.stopLiveFx();
    P.connectMainOutput();
  }
  Object.assign(P, { anyFxEnabled, fxSnapshot, fxSettingsKey, getDecodeContext, decodeTrack, liveFxActive, stopLiveFxOscillators, stopLiveFx, normalizeBakeDelay, bakeDelayMs, wireLiveFxOutput, ensureLiveFx, syncLiveFx });
}
